<script setup lang="ts">
import { Plus, Search } from 'lucide-vue-next'
import type { Restaurant } from '../../../shared/domain'
const app=useApp();const list=ref<Restaurant[]>([]);const summary=ref<any[]>([]);const query=ref('');const error=ref('');const loading=ref(false);const filtered=computed(()=>list.value.filter(r=>`${r.name}${r.area}`.includes(query.value)))
async function load(){if(!app.isAdmin.value)return;loading.value=true;try{[list.value,summary.value]=await Promise.all([app.api<Restaurant[]>('/api/admin/restaurants'),app.api<any[]>('/api/admin/summary')])}catch{error.value='管理情報を取得できませんでした。'}finally{loading.value=false}}
watch(()=>app.isAdmin.value,()=>load(),{immediate:true});useHead({title:'店舗管理 | ひとくち大阪',meta:[{name:'robots',content:'noindex'}]})
</script>
<template><section class="page"><div class="section-heading"><div><div class="eyebrow">EDITOR’S DESK</div><h1>店舗管理</h1><p>次のおいしい出会いを、ここから。</p></div><NuxtLink v-if="app.isAdmin.value" to="/admin/restaurants/new" class="button primary"><Plus :size="18"/>店舗を追加</NuxtLink></div><ClientOnly><div v-if="!app.isAdmin.value" class="empty-state"><h2>管理者ログインが必要です</h2><p>{{app.demo?'Supabaseを設定し、管理者アカウントを登録すると利用できます。':'管理者アカウントでログインしてください。'}}</p><NuxtLink to="/account" class="button primary">ログインへ</NuxtLink></div><template v-else><div class="input-icon search-box"><Search :size="18"/><input v-model="query" aria-label="店舗名・エリアで検索" placeholder="店舗名・エリアで検索"/></div><p v-if="loading" role="status">読み込み中…</p><p v-if="error" class="error">{{error}}<button @click="load">再試行</button></p><div class="admin-table"><div v-for="r in filtered" :key="r.id" class="admin-row"><img :src="r.coverImageUrl" :alt="r.name"/><div><strong>{{r.name}}</strong><p>{{r.area}} · {{r.status==='published'?'公開中':r.status==='closed'?'閉店・休止':'非公開'}}</p><small v-if="summary.find(s=>s.restaurant_id===r.id)">アンケート {{summary.find(s=>s.restaurant_id===r.id).answer_count}}件 / 平均 {{Number(summary.find(s=>s.restaurant_id===r.id).mean).toFixed(1)}}</small></div><NuxtLink :to="`/admin/restaurants/${r.id}`" class="button secondary">編集</NuxtLink></div></div><p v-if="!loading&&!filtered.length" class="empty-state">店舗がありません。「店舗を追加」から登録できます。</p></template></ClientOnly></section></template>
